SELECT  ?var1Label ?var2 ?var3 ?var4 ?var5 ?var6
WHERE
  { OPTIONAL
      { wde:Q3867631  rdfs:label  ?var1Label
        FILTER ( lang(?var1Label) = ?var7 )
        VALUES ( ?var7 ?var8 ) {
          ( "undefined" 1 )
          ( "en" 2 )
          ( "de" 3 )
          ( "fr" 4 )
          ( "it" 5 )
        }
      }
    OPTIONAL
      { wde:Q3867631  wdt:P18  ?var3 }
    OPTIONAL
      { wde:Q3867631  <urn:dboabstract>  ?var2
        FILTER ( lang(?var2) = "undefined" )
      }
    OPTIONAL
      { wde:Q3867631  wdt:P625  ?var4 }
    OPTIONAL
      { ?var6  rdf:type        url:Article ;
               url:about       wde:Q3867631 ;
               url:inLanguage  "undefined" ;
               url:isPartOf    <https://undefined.wikipedia.org/>
